SELECT r.BUSINESS_RULE_ID AS row_id, r.ACTIVE_FLAG AS active_flag, CASE WHEN r.PIPELINE_ID = t.PIPELINE_ID THEN 'Y' ELSE 'N' END AS well_formed, r.TASK_ID AS task_id, r.TARGET_TABLE_ID AS table_id, p.PIPELINE_CODE AS pipeline_code, t.TASK_CODE AS task_code, r.BUSINESS_RULE_NAME AS business_rule_name, r.SEQUENCE_NUMBER AS sequence_number, r.BUSINESS_RULE_TYPE AS business_rule_type, r.BUSINESS_RULE_LEVEL AS business_rule_level, r.BUSINESS_RULE_KEY_COLUMN AS business_rule_key_column, o.CATALOG_NAME AS catalog_name, o.SCHEMA_NAME AS schema_name, o.TABLE_NAME AS table_name, r.BUSINESS_RULE_SQL AS business_rule_sql FROM CFG_BUSINESS_RULES r JOIN CFG_TASKS t ON t.TASK_ID = r.TASK_ID JOIN CFG_PIPELINES p ON p.PIPELINE_ID = t.PIPELINE_ID JOIN CFG_TABLES o ON o.TABLE_ID=r.TARGET_TABLE_ID WHERE p.PROJECT_ID=:project_id ORDER BY 1
